 road:'<path d="M8 3 4 21M16 3l4 18M12 5v3M12 11v3M12 17v3"/>',
 water:'<path d="M3 15c3-3 5-3 8 0s5 3 8 0M3 9c3-3 5-3 8 0s5 3 8 0"/>',
